Bind(y,A,B)[x:=s]=\begin{cases}
Bind(y,A',B),&y=x,\\
Bind(y,A',B[x:=s]),&y\ne x,\ y\notin FV(s),\\
Bind(z,A',(B[y:=z])[x:=s]),&y\ne x,\ y\in FV(s).
\end{cases}

(let\ y:=a:A\ in\ b)[x:=s]=\begin{cases}
let\ y:=a':A'\ in\ b,&y=x,\\
let\ y:=a':A'\ in\ b[x:=s],&y\ne x,\ y\notin FV(s),\\
let\ z:=a':A'\ in\ (b[y:=z])[x:=s],&y\ne x,\ y\in FV(s),
\end{cases}
